// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // helper counterparty that always accepts the transferFrom call and returns success
    contract Accepting {
        // match selector transferFrom(address,address,uint256)
        function transferFrom(address, address, uint256) external pure returns (bool) {
            return true;
        }
    }

    // note: we cannot nest contract definitions in Foundry tests; move helper outside if needed
    function setUp() public { c = new C(); }

    // The test fuzzes: from address, array of recipients, and array of values
    // We cannot pass dynamic arrays directly as parameters to tests in some setups,
    // but Foundry supports fuzzing bytes/uint256 and addresses; here we use bytes to encode arrays
    // To keep it simple and fully fuzzed, we'll fuzz two uint256 values and an address and construct arrays.
    // However the requirement was to fuzz deciding values; we choose: address fromAddr, address callee, uint256 v0
    function testFuzz_property(address fromAddr, address calleeSeed, uint256 v0) public {
        // 1) ensure _tos length > 0 by constructing a single-element array
        address[] memory tos = new address[](1);
        uint[] memory vals = new uint[](1);

        // Deploy an accepting helper and use its address as the callee the contract will call.
        // The fuzzer still supplies calleeSeed but we must use a deployed contract for the external call to succeed
        Accepting helper = new Accepting();
        address helperAddr = address(helper);

        tos[0] = fromAddr; // put something admissible (fuzzer-chosen) as recipient
        // bound the value to a reasonable range but keep it wide
        vals[0] = bound(v0, 0, type(uint256).max);

        // Call transfer and capture its returned boolean via try/catch to observe returned value
        bool ok;
        try c.transfer(fromAddr, helperAddr, tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            // If it reverts, mark as false (but reference should only revert when _tos.length == 0 which we avoid)
            ok = false;
        }

        // The universal property: for any admissible input with non-empty _tos, reference C returns true.
        // Mutant that flips final return to false will make ok == false for successful calls; thus
        // assertTrue(ok) will pass on reference for all inputs and fail on mutant for some input.
        assertTrue(ok);
    }
}

// Minimal adversarial helper deployed above moved outside per solidity rules
contract Accepting {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
